<?php $title='Học kỳ & đợt đăng ký';include dirname(__DIR__,2).'/layout/header.php';?><div class="toolbar"><h2>Học kỳ & đợt đăng ký tín chỉ</h2><a class="btn" href="<?=e(BASE_URL)?>?r=admin/semester/create">+ Thêm học kỳ</a></div><div class="card"><table><tr><th>Học kỳ</th><th>Thời gian học</th><th>Thời gian đăng ký</th><th>Trạng thái đăng ký</th><th>Thao tác</th></tr><?php foreach($rows as $s):?><tr><td><?=e($s['name'])?></td><td><?=e($s['study_start'])?> → <?=e($s['study_end'])?></td><td><?=e($s['registration_start'])?> → <?=e($s['registration_end'])?></td><td><span class="badge <?=!$s['registration_open']?'off':''?>"><?=$s['registration_open']?'Đang mở':'Đang đóng'?></span></td><td class="actions"><form method="post" action="<?=e(BASE_URL)?>?r=admin/semester/toggle"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="btn small green"><?=$s['registration_open']?'Đóng đăng ký':'Mở đăng ký'?></button></form><a class="btn small secondary" href="<?=e(BASE_URL)?>?r=admin/semester/edit&id=<?=$s['id']?>">Sửa</a><form method="post" action="<?=e(BASE_URL)?>?r=admin/semester/delete" onsubmit="return confirm('Xóa học kỳ?')"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="btn small danger">Xóa</button></form></td></tr><?php endforeach;?></table></div><?php include dirname(__DIR__,2).'/layout/footer.php';?>
